import "core-js/modules/es.array.push.js";
import * as echarts from 'echarts';
import { getOverviewAPI, getCheckInTrendAPI, getCategoryOccupancyAPI, getRevenueTrendAPI } from '@/api/stats';
export default {
  name: 'Statistics',
  data() {
    return {
      loading: false,
      overview: {},
      charts: []
    };
  },
  computed: {
    statCards() {
      const o = this.overview;
      return [{
        label: '总房间数',
        value: o.totalRooms || 0,
        icon: 'el-icon-office-building',
        color: '#c9a962'
      }, {
        label: '今日入住率',
        value: (o.todayOccupancyRate || 0) + '%',
        icon: 'el-icon-data-analysis',
        color: '#67c23a'
      }, {
        label: '可用房间',
        value: o.availableRooms || 0,
        icon: 'el-icon-key',
        color: '#e6a23c'
      }, {
        label: '本月营收',
        value: '¥' + (o.monthRevenue || 0),
        icon: 'el-icon-coin',
        color: '#f56c6c'
      }, {
        label: '注册会员',
        value: o.totalMembers || 0,
        icon: 'el-icon-user',
        color: '#909399'
      }, {
        label: '待处理预约',
        value: o.pendingAppointments || 0,
        icon: 'el-icon-bell',
        color: '#b88230'
      }];
    }
  },
  mounted() {
    this.fetchData();
    window.addEventListener('resize', this.handleResize);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.handleResize);
    this.charts.forEach(c => c.dispose());
  },
  methods: {
    async fetchData() {
      this.loading = true;
      try {
        const [overview, trend, category, revenue] = await Promise.all([getOverviewAPI(), getCheckInTrendAPI(7), getCategoryOccupancyAPI(), getRevenueTrendAPI(6)]);
        this.overview = overview.data;
        this.$nextTick(() => {
          this.renderTrendChart(trend.data);
          this.renderCategoryChart(category.data);
          this.renderRevenueChart(revenue.data);
        });
      } finally {
        this.loading = false;
      }
    },
    initChart(ref) {
      const chart = echarts.init(this.$refs[ref]);
      this.charts.push(chart);
      return chart;
    },
    renderTrendChart(data) {
      const chart = this.initChart('trendChart');
      chart.setOption({
        tooltip: {
          trigger: 'axis'
        },
        grid: {
          left: 50,
          right: 20,
          top: 30,
          bottom: 30
        },
        xAxis: {
          type: 'category',
          data: data.dates,
          axisLabel: {
            color: '#666'
          }
        },
        yAxis: {
          type: 'value',
          minInterval: 1,
          axisLabel: {
            color: '#666'
          }
        },
        series: [{
          name: '入住数',
          type: 'line',
          smooth: true,
          data: data.counts,
          areaStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{
              offset: 0,
              color: 'rgba(201,169,98,0.3)'
            }, {
              offset: 1,
              color: 'rgba(201,169,98,0.02)'
            }])
          },
          lineStyle: {
            color: '#c9a962',
            width: 3
          },
          itemStyle: {
            color: '#c9a962'
          }
        }]
      });
    },
    renderCategoryChart(data) {
      const chart = this.initChart('categoryChart');
      const pieData = (data.categoryNames || []).map((name, i) => ({
        name,
        value: (data.occupied || [])[i] || 0
      }));
      chart.setOption({
        tooltip: {
          trigger: 'item',
          formatter: '{b}: {c}间 ({d}%)'
        },
        legend: {
          bottom: 0,
          type: 'scroll'
        },
        color: ['#c9a962', '#67c23a', '#e6a23c', '#f56c6c', '#909399', '#a88b4a'],
        series: [{
          type: 'pie',
          radius: ['40%', '65%'],
          center: ['50%', '45%'],
          data: pieData,
          label: {
            formatter: '{b}\n{d}%'
          },
          emphasis: {
            itemStyle: {
              shadowBlur: 10,
              shadowColor: 'rgba(0,0,0,0.2)'
            }
          }
        }]
      });
    },
    renderRevenueChart(data) {
      const chart = this.initChart('revenueChart');
      chart.setOption({
        tooltip: {
          trigger: 'axis',
          formatter: '{b}<br/>营收: ¥{c}'
        },
        grid: {
          left: 60,
          right: 20,
          top: 30,
          bottom: 30
        },
        xAxis: {
          type: 'category',
          data: data.months,
          axisLabel: {
            color: '#666'
          }
        },
        yAxis: {
          type: 'value',
          axisLabel: {
            color: '#666',
            formatter: '¥{value}'
          }
        },
        series: [{
          name: '营收',
          type: 'bar',
          barWidth: '40%',
          data: (data.revenues || []).map(v => Number(v)),
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{
              offset: 0,
              color: '#67c23a'
            }, {
              offset: 1,
              color: '#95d475'
            }]),
            borderRadius: [6, 6, 0, 0]
          }
        }]
      });
    },
    handleResize() {
      this.charts.forEach(c => c.resize());
    }
  }
};
